local mt=(getgenv and getgenv()) or _ENV or _G
local QH={} for i=97,122 do QH[#QH+1]=string.char(i) end
local Ot={12,15,1,4,19,20,18,9,14,7}
local UD="" for i=1,#Ot do UD=UD..QH[Ot[i]] end
local Az=mt and mt[UD]
local Kt=type(Az)=="function"
if Kt then
local mV={8,15,15,11,6,21,14,3,20,9,15,14}
local qB="" for i=1,#mV do qB=qB..QH[mV[i]] end
local IL={18,5,19,20,15,18,5,6,21,14,3,20,9,15,14}
local Av="" for i=1,#IL do Av=Av..QH[IL[i]] end
local wX=mt[qB]
local kr=mt[Av]
local WN=false
if type(wX)=="function" and type(kr)=="function" then
local cz=function() return 5 end
local qh=pcall(wX,cz,function() return -777 end)
if qh and cz()==-777 then
local Ur=pcall(kr,cz)
WN=(Ur and cz()==5)
end
if not WN then pcall(kr,cz) end
if not WN and type(mt.math)=="table" and type(mt.math.abs)=="function" then
local Sl=mt.math.abs
if Sl(5)==5 then
local qJ,aV=pcall(wX,Sl,function() return -777 end)
if qJ and Sl(5)==-777 then
local oL=pcall(kr,Sl)
WN=(oL and Sl(5)==5)
if not WN then pcall(kr,Sl) mt.math.abs=(type(aV)=="function" and aV) or function(v) if v<0 then return -v end return v end end
end
end
end
if WN then
local CB={Az,wX,kr}
local ep=mt.string
if type(ep)=="table" then
CB[#CB+1]=ep.char CB[#CB+1]=ep.byte CB[#CB+1]=ep.sub CB[#CB+1]=ep.rep CB[#CB+1]=ep.len
end
if type(mt.table)=="table" and mt.table.concat then CB[#CB+1]=mt.table.concat end
if mt.pcall then CB[#CB+1]=mt.pcall end
if type(mt.math)=="table" and mt.math.floor then CB[#CB+1]=mt.math.floor end
for ed=1,#CB do local zt=CB[ed] if type(zt)=="function" then pcall(kr,zt) end end
end
end
end
if not Kt then return nil end

